spec.root_selector:
(
  $filtered := $[target_group in ${target_group:json} or "$__all" in ${target_group:json}][
    $match(target_name, /^${target_name:regex}$/) and $match(network_ip, /^${network_ip:regex}$/)
  ];
  $count($filtered) = 0
    ? [{ "target_group": "⚠ Please choose either machine or IP, not a mismatched pair" }]
    : $filtered
)
